PUNCT=re.compile(r'[\s、。！？!?…・「」『』（）()\[\]【】]')
def clean(x): return PUNCT.sub('',x)
def main():
 raw=FRAMES.read_bytes(); data=json.loads(raw.decode('utf8')); frames=data['frames']; ids=[f['id'] for f in frames]
 changes=[]; assertions=[]
 for f in frames:
  fid=f['id']; src=R.get(fid,fid)
  if src not in L: raise RuntimeError('no bundle '+fid)
  cards=copy.deepcopy(L[src]); lyric=f['caption']['japanese']; joined=''.join(x['token'] for x in cards)
  assertion={'frameId':fid,'expected':clean(lyric),'tokenConcatenation':clean(joined),'passed':clean(lyric)==clean(joined)}
  assertions.append(assertion)
  if not assertion['passed']: raise RuntimeError('coverage mismatch '+fid+' '+repr(assertion))
  changes.append({'frameId':fid,'field':'grammarCards','old':f.get('grammarCards',[]),'new':cards,'confidence':0.96,'evidence':['逐字覆盖断言通过；固定语法仅在不遗漏任何语义词或助词时合并。'],'changesTokenStructure':True})
 if len(changes)!=61 or not all(a['passed'] for a in assertions): raise RuntimeError('incomplete coverage')
 out={'schemaVersion':4,'reviewRole':'grammar','scope':{'frameIds':ids,'coverage':'all-61-japanese-lyric-frames','coverageAssertions':assertions},'baseFrameSha256':hashlib.sha256(raw).hexdigest(),'changes':changes,'reviewNotes':['强制逐字覆盖：每句 token 拼接（忽略空格与标点）等于原歌词。','每个助词单独成卡并使用 functionZh；活用整体保留为动词卡。','posZh 保持简短，grammarStructureZh 仅作审阅数据。']}
